<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/functions.php';require_once __DIR__.'/includes/csrf.php';$u=require_login();$id=(int)($_GET['conversation_id']??0);$s=db()->prepare('SELECT c.*,l.title FROM conversations c JOIN listings l ON l.id=c.listing_id WHERE c.id=? AND (c.buyer_id=? OR c.seller_id=?)');$s->execute([$id,$u['id'],$u['id']]);$c=$s->fetch();if(!$c){http_response_code(403);exit('Conversation not available.');}db()->prepare('UPDATE messages SET is_read=1 WHERE conversation_id=? AND sender_id<>?')->execute([$id,$u['id']]);$pageTitle='Chat';include __DIR__.'/includes/header.php';?><div class="section-head"><div><h2><?=e($c['title'])?></h2><p>Conversation is private to the buyer and seller.</p></div></div><div class="chat"><div class="chat-log" data-chat-log data-conversation="<?=$id?>"></div><form class="chat-form" method="post" action="/api/chat.php"><?=csrf_field()?><input type="hidden" name="action" value="send"><input type="hidden" name="conversation_id" value="<?=$id?>"><input name="message" maxlength="2000" required placeholder="Write a message"><button class="btn">Send</button></form></div><?php include __DIR__.'/includes/footer.php';?>